/** Mini Feuille de route (format colonnaire de fetchTable) : jeu de test de la hiérarchie catégorie → projet → chantier → tâche → sous-tâche. */
const s = (iso, hourUtc = 0) => Date.parse(`${iso}T00:00:00Z`) / 1000 + hourUtc * 3600;
export function columnar(rows) {
  const cols = new Set(['id']);
  rows.forEach((r) => Object.keys(r).forEach((k) => cols.add(k)));
  return Object.fromEntries([...cols].map((c) => [c, rows.map((r) => (c in r ? r[c] : null))]));
}
